CREATE DATABASE IF NOT EXISTS controle_cacambas CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE controle_cacambas;

CREATE TABLE usuarios (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,senha VARCHAR(255) NOT NULL,nivel ENUM('administrador','gerente','operador','cliente') NOT NULL DEFAULT 'operador',status TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE clientes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(150) NOT NULL,documento VARCHAR(20) NOT NULL UNIQUE,tipo_documento ENUM('CPF','CNPJ') NOT NULL,email VARCHAR(190),telefone VARCHAR(30),celular VARCHAR(30),cep VARCHAR(10),endereco VARCHAR(180),numero VARCHAR(20),complemento VARCHAR(100),bairro VARCHAR(100),cidade VARCHAR(100),estado CHAR(2),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cacambas (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,numero VARCHAR(30) NOT NULL UNIQUE,tipo ENUM('3m3','4m3','5m3','7m3') NOT NULL,status ENUM('disponivel','em_uso','manutencao','inativa') NOT NULL DEFAULT 'disponivel',localizacao VARCHAR(180),observacao TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE motoristas (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(150) NOT NULL,cnh VARCHAR(30) NOT NULL UNIQUE,validade_cnh DATE,telefone VARCHAR(30),status TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE fornecedores (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,razao_social VARCHAR(180) NOT NULL,cnpj VARCHAR(20),telefone VARCHAR(30),email VARCHAR(190),servico VARCHAR(180));
CREATE TABLE pedidos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,cliente_id BIGINT UNSIGNED NOT NULL,cacamba_id BIGINT UNSIGNED,motorista_id BIGINT UNSIGNED,data_pedido DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,data_entrega DATETIME,data_retirada_prevista DATETIME,data_retirada_real DATETIME,endereco_entrega TEXT,valor DECIMAL(12,2) NOT NULL DEFAULT 0,forma_pagamento VARCHAR(40),status ENUM('orcamento','confirmado','entregue','retirado','cancelado') NOT NULL DEFAULT 'orcamento',observacao TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(cliente_id) REFERENCES clientes(id),FOREIGN KEY(cacamba_id) REFERENCES cacambas(id) ON DELETE SET NULL,FOREIGN KEY(motorista_id) REFERENCES motoristas(id) ON DELETE SET NULL);
CREATE TABLE pagamentos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,pedido_id BIGINT UNSIGNED NOT NULL,data_pagamento DATE,valor DECIMAL(12,2) NOT NULL,forma_pagamento VARCHAR(40),observacao TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(pedido_id) REFERENCES pedidos(id) ON DELETE CASCADE);
CREATE TABLE logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT UNSIGNED,acao VARCHAR(120) NOT NULL,tabela_afetada VARCHAR(80),registro_id BIGINT UNSIGNED,data_hora DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,ip VARCHAR(45),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE SET NULL);
CREATE TABLE configuracoes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,chave VARCHAR(100) NOT NULL UNIQUE,valor TEXT);
CREATE TABLE login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL,ip VARCHAR(45) NOT NULL,success TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(email,ip,created_at));
CREATE INDEX idx_pedidos_status ON pedidos(status); CREATE INDEX idx_pedidos_datas ON pedidos(data_entrega,data_retirada_prevista); CREATE INDEX idx_pagamentos_data ON pagamentos(data_pagamento);
